use vstd::prelude::*;

verus! {

    // Transpose a nonempty m×n matrix of f32's.
    // Precondition: x has at least one row, and all rows are the same length.
    // Postcondition: result is n×m, and result[j][i] == x[i][j].
    fn numpy_matrix_transpose(x: Vec<Vec<f32>>) -> Vec<Vec<f32>>
        requires
            x.len() > 0,
            // all rows have the same length
            forall |i: usize| i < x.len() ==> x[i].len() == x[0].len(),
        ensures
            // result has n = x[0].len() rows,
            result.len() == x[0].len(),
            // each result row has length m = x.len()
            forall |j: usize| j < result.len() ==> result[j].len() == x.len(),
            // and for all valid i< m, j< n, the data is transposed
            forall |i: usize, j: usize|
                i < x.len() && j < x[0].len()
                ==> result[j][i] == x[i][j],
    {
        let m = x.len();
        let n = x[0].len();

        let mut result: Vec<Vec<f32>> = Vec::with_capacity(n);

        // Build each of the n rows of the transpose.
        for j in 0..n
            invariant
                // j has advanced from 0 up to n
                j <= n,
                // we have pushed exactly j rows so far
                result.len() == j,
                // each of those j rows is length m, and is the appropriate slice
                forall |jj: usize, ii: usize|
                    jj < j && ii < m ==>
                        result[jj].len() == m
                        && result[jj][ii] == x[ii][jj],
            decreases n - j
        {
            let mut new_row: Vec<f32> = Vec::with_capacity(m);

            // Build the j-th row by pulling out x[0][j], x[1][j], …, x[m-1][j].
            for i in 0..m
                invariant
                    i <= m,
                    new_row.len() == i,
                    // the length‐i prefix of new_row is exactly [ x[0][j], …, x[i-1][j] ]
                    forall |ii: usize| ii < i ==> new_row[ii] == x[ii][j],
                decreases m - i
            {
                new_row.push(x[i][j]);
            }

            result.push(new_row);
        }

        result
    }
}

